CREATE OR REPLACE FUNCTION public.field_retire_beds(p_implementation_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.implementation_guide_items g SET enabled=false WHERE g.implementation_id=p_implementation_id AND g.amenity_key LIKE 'r:%:camas' AND NOT EXISTS(SELECT 1 FROM public.implementation_amenities a CROSS JOIN LATERAL jsonb_array_elements(a.data->'rooms') AS elem(value) WHERE a.implementation_id=p_implementation_id AND g.amenity_key=('r:'||(elem.value->>'id')||':camas')) $$;
REVOKE ALL ON FUNCTION public.field_retire_beds(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.field_retire_beds(uuid) TO service_role;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.field_registration_prepare_inventory(text)'::regprocedure) INTO definition; definition:=replace(definition,'UPDATE public.implementation_guide_items SET enabled=false WHERE implementation_id=p.id AND amenity_key LIKE ''r:%:camas'' AND NOT EXISTS(SELECT 1 FROM public.implementation_amenities a,jsonb_array_elements(a.data->''rooms'') room WHERE a.implementation_id=p.id AND amenity_key=''r:''||(room->>''id'')||'':camas'');','PERFORM public.field_retire_beds(p.id);'); EXECUTE definition; END $$;